class starter {
	public static void main(String args[]) {
		System.out.println("Your fortune cookie's fortune is:");
		int num = (int)(Math.random()*10);
		if(num == 0){
			System.out.print("When you finish reading this sentence, you will forget you ever killed that man");
		}
		if(num == 1){
			System.out.print("You are now immortal");
		}
		if(num == 2){
			System.out.print("");
		}
		if(num == 3){
			System.out.print("Does anyone even like the taste of fortune cookies? I don't");
		}
		if(num == 4){
			System.out.print("I know what you did");
		}
		if(num == 5){
			System.out.print("Made In China");
		}
		if(num == 6){
			System.out.print("starter.java:30: error: ';' expected\n			System.out.print(\"\")\n      		    			    ^");
		}
		if(num == 7){
			System.out.print("You will find love in ERROR:INFINITY IS NOT A NUMBER days ");
		}
		if(num == 8){
			System.out.print("Buy premium to see your fortune, only 29.99 a month!");
		}
		if(num == 9){
			System.out.print("idk");
		}
		System.out.println();
	}
}
